import sys
sys.setrecursionlimit(300005)

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
        except StopIteration:
            break

        adj = [[] for _ in range(n + 1)]

        for _ in range(n - 1):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)

        if n == 1:
            results.append("0")
            continue

        children = [None] * (n + 1)
        parent = [0] * (n + 1)
        stack = [1]
        visited = [False] * (n + 1)
        visited[1] = True

        while stack:
            u = stack.pop()
            child_list = []
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    child_list.append(v)
                    stack.append(v)
            children[u] = child_list

        def dfs(u):
            if not children[u]:
                return 1, 1

            res = []
            for v in children[u]:
                res.append(dfs(v))

            res.sort(key=lambda x: x[1], reverse=True)

            total_saved = 0
            for i, (s, h) in enumerate(res):
                if i == 0:
                    total_saved += s
                else:
                    total_saved += h

            max_h = 0
            for i, (s, h) in enumerate(children[u]):
                pass

            best_h = 0
            current_sum = 0
            for i, (s, h) in enumerate(sorted(res, key=lambda x: x[1], reverse=True)):
                if i == 0:
                    current_sum = s
                else:
                    current_sum += h
                if i == 0:
                    best_h = max(best_h, h)
                else:
                    best_h = max(best_h, h)

            final_s = 0
            for i, (s, h) in enumerate(sort_res := sorted(res, key=lambda x: x[1], reverse=True)):
                pass

            sort_res = sorted(res, key=lambda x: x[1], reverse=True)
            s_val = 0
            h_val = 0

            for i, (s, h) in enumerate(sort_res):
                if i == 0:
                    s_val += s
                else:
                    s_val += h

            h_val = sort_res[0][1]
            for i in range(1, len(sort_res)):
                h_val = max(h_val, sort_res[i][1])

            return s_val, h_val

        if not children[1]:
            results.append("0")
            continue

        s_root, h_root = dfs(1)
        ans = s_root - 1
        results.append(str(ans))

    print('\n'.join(results))

if __name__ == '__main__':
    solve()
